import Foundation

// The plan side of the domain (docs/product/handoff-produto.md, Modelo de domínio). Every entity
// follows docs/decisions/0009: client-generated UUIDv7 id, athlete_id, timestamps, soft delete.
// Ids are generated by the caller (HTSPersistence.UUIDv7) so this module stays free of storage.

/// Temporada: a named sequence of arcs (Jiu-Jitsu, Performance). Arcs unlock in order and only one season is
/// active at a time (docs/decisions/0029).
public struct Season: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    public var name: String
    public var position: Int
    public var active: Bool
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, name: String, position: Int, active: Bool = false, createdAt: Date,
        updatedAt: Date? = nil, deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.name = name
        self.position = position
        self.active = active
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }
}

/// A phase of the program: N workout templates × weeks.
public struct Arc: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    /// Nil for free arcs (Manutenção), which belong to no season.
    public var seasonId: UUID?
    public var name: String
    public var kanji: String?
    /// The coach's real program this arc follows.
    public var program: String?
    public var kind: ArcKind
    /// Nil for filler arcs, which have no duration.
    public var weeks: Int?
    public var startDate: LocalDate?
    public var status: ArcStatus
    public var position: Int
    /// "Recomeçar contagem": sessions before this instant do not count for the arc.
    public var countResetAt: Date?
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, seasonId: UUID?, name: String, kanji: String? = nil, program: String? = nil,
        kind: ArcKind = .normal, weeks: Int?, startDate: LocalDate?, status: ArcStatus = .queued, position: Int,
        countResetAt: Date? = nil, createdAt: Date, updatedAt: Date? = nil, deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.seasonId = seasonId
        self.name = name
        self.kanji = kanji
        self.program = program
        self.kind = kind
        self.weeks = weeks
        self.startDate = startDate
        self.status = status
        self.position = position
        self.countResetAt = countResetAt
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }
}

/// The recipe of a workout inside an arc (A · Linha de Frente). Reuse in another arc copies it
/// (docs/decisions/0015); `sourceTemplateId` keeps the origin.
public struct WorkoutTemplate: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    public var arcId: UUID
    public var sourceTemplateId: UUID?
    public var letter: String
    public var name: String
    public var focus: String?
    public var position: Int
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, arcId: UUID, sourceTemplateId: UUID? = nil, letter: String, name: String,
        focus: String? = nil, position: Int, createdAt: Date, updatedAt: Date? = nil, deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.arcId = arcId
        self.sourceTemplateId = sourceTemplateId
        self.letter = letter
        self.name = name
        self.focus = focus
        self.position = position
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }
}

public struct Block: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    public var workoutTemplateId: UUID
    public var kind: BlockKind
    public var attributes: [Attribute]
    /// Only for fight rounds (6 to 12 min).
    public var durationMinutes: Int?
    public var position: Int
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, workoutTemplateId: UUID, kind: BlockKind, attributes: [Attribute],
        durationMinutes: Int? = nil, position: Int, createdAt: Date, updatedAt: Date? = nil, deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.workoutTemplateId = workoutTemplateId
        self.kind = kind
        self.attributes = attributes
        self.durationMinutes = durationMinutes
        self.position = position
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }
}

/// Catalog exercise. Free text, deduplicated by `normalizedName` (docs/decisions/0016).
public struct Exercise: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    public var name: String
    public var normalizedName: String
    public var defaultAttribute: Attribute?
    public var unit: ExerciseUnit
    public var perSide: Bool
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, name: String, defaultAttribute: Attribute? = nil, unit: ExerciseUnit = .reps,
        perSide: Bool = false, createdAt: Date, updatedAt: Date? = nil, deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.name = name.trimmingCharacters(in: .whitespacesAndNewlines)
        self.normalizedName = ExerciseName.normalize(name)
        self.defaultAttribute = defaultAttribute
        self.unit = unit
        self.perSide = perSide
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }
}

/// An exercise inside a block: sets × target, optional own rest.
public struct PrescribedExercise: Identifiable, Hashable, Sendable, Codable {
    public var id: UUID
    public var athleteId: UUID
    public var blockId: UUID
    public var exerciseId: UUID
    /// Sets can be a range ("3 a 4"); equal values mean a fixed count.
    public var setsMin: Int
    public var setsMax: Int
    public var targets: [SetTarget]
    public var restSeconds: Int?
    public var position: Int
    public var createdAt: Date
    public var updatedAt: Date
    public var deletedAt: Date?

    public init(
        id: UUID, athleteId: UUID, blockId: UUID, exerciseId: UUID, setsMin: Int, setsMax: Int? = nil,
        targets: [SetTarget], restSeconds: Int? = nil, position: Int, createdAt: Date, updatedAt: Date? = nil,
        deletedAt: Date? = nil
    ) {
        self.id = id
        self.athleteId = athleteId
        self.blockId = blockId
        self.exerciseId = exerciseId
        self.setsMin = setsMin
        self.setsMax = setsMax ?? setsMin
        self.targets = targets
        self.restSeconds = restSeconds
        self.position = position
        self.createdAt = createdAt.roundedToMilliseconds
        self.updatedAt = (updatedAt ?? createdAt).roundedToMilliseconds
        self.deletedAt = deletedAt?.roundedToMilliseconds
    }

    public var isValid: Bool {
        setsMin > 0 && setsMin <= setsMax && targets.fits(setsMax: setsMax)
    }
}
